// Population count circuit (255-bit input)
module PopCount255 (
    input  [254:0] in,
    output [ 7:0]  out
);
    wire  [12:0] stage1 [0:12];
    wire  [ 6:0] stage2 [0:6];
    wire  [ 3:0] stage3 [0:3];
    wire  [ 1:0] stage4 [0:1];
    wire  [0:0] stage5;
    genvar i, j, k, l, m;
    generate
        for (i = 0; i < 13; i = i + 1) begin
            if (i == 0) begin
                stage1[i] = in[0];
            end else begin
                stage1[i] = stage1[i-1] + in[1<<(i-1)];
            end
        end
        for (j = 0; j < 7; j = j + 1) begin
            if (j < 2) begin
                stage2[j] = stage1[j];
            end else begin
                stage2[j] = stage2[j-1] + stage1[1<<j];
            end
        end
        for (k = 0; k < 4; k = k + 1) begin
            if (k < 3) begin
                stage3[k] = stage2[k];
            end else begin
                stage3[k] = stage3[k-1] + stage2[1<<k];
            end
        end
        for (l = 0; l < 2; l = l + 1) begin
            if (l < 1) begin
                stage4[l] = stage3[l];
            end else begin
                stage4[l] = stage4[l-1] + stage3[1<<l];
            end
        end
        stage5 = stage4[0] + stage4[1];
    endgenerate
    assign out = stage5;
endmodule

