// One-bit wide population count stage, counting one, two, or three bits.
// Takes an 8-bit input and returns the population count of the 255-bit
// input vector that corresponds to the three bits.
module pc3_stage (
    input [7:0] in,
    input [254:0] vec,
    output reg [7:0] out
);
    wire [7:0] c1 = vec[in];
    wire [7:0] c2 = vec[in + 1];
    wire [7:0] c3 = vec[in + 2];
    always @* out = c1 + c2 + c3;
endmodule

