// One-stage shift register stage, with register, AND, and a chain of
// three combinational logic stages (the critical path is roughly the
// same as the register itself; pipeline the registers to go faster).
module TopModule(
    input  clk,
    input  w,
    input  R,
    input  E,
    input  L,
    output Q
);
    reg q0, q1, q2;
    wire w0, w1, w2;
    wire E0, E1, E2;
    wire [1:0] G;
    assign G = {E2, E1};
    assign Q = q2;
    // Stage 0: register + AND
    always @(posedge clk) begin
        q0 <= E ? R : w;
        w0 <= q0 & L;
    end
    // Stage 1: register + AND
    always @(posedge clk) begin
        q1 <= E0 ? R : w0;
        w1 <= q1 & L;
    end
    // Stage 2: register
    always @(posedge clk) begin
        q2 <= E1 ? R : w1;
        w2 <= q2 & L;
    end
    // Gate choice combinational logic
    always @(*) begin
        E0 = G[0];
        E1 = G[1] & w0;
        E2 = G[1] & w1;
    end
endmodule

