// 4-stage FSM, one-hot state encoding
module FSM (
    input clk,
    input reset,
    output reg [3:0] state,
    output reg shift_ena
);
    always @(posedge clk) begin
        if (reset) begin
            state <= 4'b0001;
            shift_ena <= 1;
        end else begin
            case (state)
                4'b0001: begin state <= 4'b0010; shift_ena <= 0; end
                4'b0010: begin state <= 4'b0100; shift_ena <= 0; end
                4'b0100: begin state <= 4'b1000; shift_ena <= 0; end
                4'b1000: begin state <= 4'b0001; shift_ena <= 1; end
            endcase
        end
    end
end

// Pattern: ABCD, where ABCD are the first 4 stages of the FSM.
// The FSM is reset when the pattern ABC is detected, and the next
// stage D is shifted in.
module PatternDetect (
    input clk,
    input reset,
    input [3:0] state,
    output reg match
);
    reg [3:0] shift_reg;
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 4'b0000;
            match <= 0;
        end else begin
            shift_reg <= {shift_reg[2:0], state};
            match <= (shift_reg == 4'b0001001);
        end
    end
end

