      3'b011: next_state = y[0] ? 3'b100 : 3'b011;
      3'b100: next_state = y[0] ? 3'b101 : 3'b100;
      3'b101: next_state = y[0] ? 3'b000 : 3'b101;
      // Self-transition on y[0] = 1
