  always @(*) begin
    for (i = 0; i < 256; i = i + 1) begin
      integer x = i % 16;
      integer y = i / 16;
      integer n =
        ((r0[(y + 16*16 - 1) % 256] & ((x + 16*16 - 1) % 16 < 8)) +
         (r0[(y + 16*16) % 256] & ((x + 16*16 - 1) % 16 < 8)) +
         (r0[(y + 16*16 + 1) % 256] & ((x + 16*16 - 1) % 16 < 8)) +
