module TopModule(
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [2:0] state, next_state;
    reg [2:0] g_reg;
    wire [2:0] g_next;
    always @* begin
        case (state)
            A: g_next = (r == 3'b000) ? 3'b000 :
                        (r == 3'b001) ? 3'b001 :
                        (r == 3'b010) ? 3'b010 : 3'b011;
            B: g_next = (r == 3'b001) ? 3'b001 :
                        (r == 3'b000) ? 3'b000 :
                        (r == 3'b010) ? 3'b010 : 3'b011;
