                        (r == 3'b001) ? 3'b001 :
                        (r == 3'b010) ? 3'b010 : 3'b011;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) begin
            state <= A;
            g_reg <= 3'b000;
