//   B (g0=1) -------r0=1-------> B
//   B (g0=1) -------r0=0-------> A
//   C (g1=1) -------r1=1-------> C
//   C (g1=1) -------r1=0-------> A
//   D (g2=1) --r0=0,r1=0,r2=1--> E
//   E        --r0=1,r1=0,r2=0--> F
//   F (g2=1) --r0=0,r1=0,r2=0--> F
//   F (g2=1) ----r0=1,r1=0,r2=0--> D
module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [2:0] state, next_state;
    reg [2:0] state_reg;
    always @(*) begin
        case (state)
            3'b001: next_state = (r == 3'b001) ? 3'b001 :
                                 (r == 3'b010) ? 3'b010 :
                                 (r == 3'b100) ? 3'b100 : 3'b000;
