// (shift_ena, counting, done). One-hot encoded state names and next-state
// logic as a combinational multiplexer (one multiplexer per state, selecting
// the next state based on the inputs). Derived the output logic as a
// combinational multiplexer (one multiplexer per state, selecting the
// output value based on the state and inputs).
module TopModule(
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,
    output reg B3_next,
    output reg S_next,
    output reg S1_next,
    output reg Count_next,
    output reg Wait_next,
    output reg done,
    output reg counting,
    output reg shift_ena
);
    wire [9:0] next_state;
    wire [9:0] next_state_table [0:7] = '{10'b0000000001, 10'b0000000010, 10'b0000000100, 10'b0000001000, 10'b0000010000, 10'b0000100000, 10'b0001000000, 10'b0010000000};
    wire [2:0] output_table [0:7] = '{3'b001, 3'b001, 3'b001, 3'b001, 3'b000, 3'b000, 3'b000, 3'b000};
    always @(*) begin
        next_state = next_state_table[state];
        {B3_next, S_next, S1_next, Count_next, Wait_next, done, counting, shift_ena} = {output_table[next_state]};
