    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [3:0] counter;
    reg [3:0] remaining;
    reg [1:0] state;
    reg [1:0] next_state;
    reg [3:0] pattern;
    wire pattern_match = (pattern == 4'b1101);
